+		t.Fatalf("Runner changed absent guided coverage to %q", got)
+	}
+	for _, test := range []struct {
+		mode     CoverageMode
+		required []string
+		valid    bool
+	}{
+		{mode: CoverageNone, valid: true},
+		{mode: CoverageSemantic, required: []string{"stdlib.os.openfile"}, valid: true},
+		{mode: CoverageNone, required: []string{"stdlib.os.openfile"}},
+		{mode: CoverageSemantic, required: []string{"unknown.probe"}},
+		{mode: "unknown"},
+	} {
+		if err := ValidateCoverage(test.mode, test.required); (err == nil) != test.valid {
+			t.Fatalf("ValidateCoverage(%q, %v) = %v; valid=%t", test.mode, test.required, err, test.valid)
+		}
+	}
+	for _, test := range []struct {
+		limit uint64
+		valid bool
+	}{
+		{limit: 0, valid: true},
+		{limit: MinimumChoiceTraceBytes, valid: true},
+		{limit: MaximumChoiceTraceBytes, valid: true},
+		{limit: 1},
+		{limit: MaximumChoiceTraceBytes + 1},
+	} {
+		if err := ValidateChoiceTraceLimit(test.limit); (err == nil) != test.valid {
+			t.Fatalf("ValidateChoiceTraceLimit(%d) = %v; valid=%t", test.limit, err, test.valid)
+		}
+	}
+	if err := ValidateChoiceCoverage(CoverageChoice, 0); err == nil {
+		t.Fatal("choice coverage without a trace succeeded")
+	}
+	if err := ValidateChoiceCoverage(CoverageChoice, MinimumChoiceTraceBytes); err != nil {
+		t.Fatal(err)
+	}
+	if err := ValidateChoiceCoverage(CoverageSemantic, 0); err != nil {
+		t.Fatal(err)
+	}
+}

ownership_and_order.body:
func runExploreWith(arguments []string, stdout, stderr io.Writer, dependencies exploreDependencies) int {
	request, status, ok := parseCampaignRequest(exploreCampaign, arguments, stdout, stderr, dependencies)
	if !ok {
		return status
	}
	reporter := request.reporter
	summary, err := dependencies.explore(context.Background(), request.campaign)
	if err != nil {
		return reportExploreFailure(summary, err, reporter, stderr)
	}
	if err := reporter.Result(summary); err != nil {
		fmt.Fprintln(stderr, err)
		return 3
	}
	return exploreSummaryStatus(summary)
}

func reportExploreFailure(summary runner.CampaignResult, err error, reporter *exploreReporter, stderr io.Writer) int {
	var diagnosticWriteErr error
	if summary.ChoiceTrace != nil {
		_, diagnosticWriteErr = fmt.Fprintf(stderr, "gomad:%s\n", formatChoiceTrace(summary.ChoiceTrace))
	}
	classification := classifyExploreError(err)
	if writeErr := reporter.Error(classification, err); writeErr != nil {
		if _, printErr := fmt.Fprintln(stderr, errors.Join(writeErr, diagnosticWriteErr)); printErr != nil {
			return 3
		}
		return 3
	}
	return exploreErrorStatus(classification)
}

func runPlanWith(arguments []string, stdout, stderr io.Writer, dependencies exploreDependencies) int {
	request, status, ok := parseCampaignRequest(planCampaign, arguments, stdout, stderr, dependencies)
	if !ok {
		return status
	}
	reporter := request.reporter
	if request.output == "" {
		if writeErr := reporter.Error("invalid_input", errors.New("gomad plan requires --output FILE")); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return 3
		}
		return 2
	}
	planned, err := dependencies.plan(context.Background(), runner.CampaignPlanSpec{Campaign: request.campaign, Output: request.output})
	if err != nil {
		classification := classifyExploreError(err)
		if writeErr := reporter.Error(classification, err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return 3
		}
		return exploreErrorStatus(classification)
	}
	if request.json {
		encoded, err := json.Marshal(planned)
		if err != nil {
			fmt.Fprintln(stderr, err)
			return 3
		}
		if _, err := fmt.Fprintf(stdout, "%s\n", encoded); err != nil {
			return 3
		}
	} else if _, err := fmt.Fprintf(stdout, "gomad plan: path=%s bundle=%s sha256=%s selected=%d target=%s\n", planned.Path, planned.BundlePath, planned.SHA256, planned.SelectionCount, planned.TargetSHA256); err != nil {
		return 3
	}
	return 0
}

// campaignOperation is the operation a parsed campaign request is for.
// gomad explore and gomad plan share one grammar; the operation decides only
// plan's fixed failure policy and whether --output is accepted.
type campaignOperation int

const (
	exploreCampaign campaignOperation = iota
	planCampaign
)

// campaignRequest is one parsed and validated gomad explore or gomad plan
// invocation: the campaign to run or freeze, plan's --output, and the
// reporter that carries the operation's events and errors.
type campaignRequest struct {
	campaign runner.CampaignSpec
	output   string
	json     bool
	reporter *exploreReporter
}

// parseCampaignRequest parses the grammar gomad explore and gomad plan share.
// It keeps flag-presence validation and reporting; Runner owns the semantic
// rules the flags map to. It resolves the working directory and the
// installation only after the flags validate. When ok is false it has
// already reported the failure and status is the exit status.

func parseCampaignRequest(operation campaignOperation, arguments []string, stdout, stderr io.Writer, dependencies exploreDependencies) (request campaignRequest, status int, ok bool) {
	flags := flag.NewFlagSet("gomad explore", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	strategy := flags.String("strategy", string(runner.StrategySeed), "seed, choice-exploration, or simulation-exploration")
	seeds := flags.String("seeds", "1", "seed set or inclusive ranges")
	count := flags.Uint64("count", 0, "explore seeds 0 through N-1")
	maxRuns := flags.Uint64("max-executions", 0, "maximum exploration candidates")
	maxChoiceDepth := flags.Uint64("max-choice-depth", 0, "maximum forced choice decisions")
	choiceStartOrdinal := flags.Uint64("choice-start-ordinal", 0, "first replay-plan decision ordinal choice exploration expands; inspect --choices lists ordinals")
	maxForcedDecisions := flags.Uint64("max-forced-decisions", 0, "maximum combined forced decisions")
	maxRuntimeDecisions := flags.Uint64("max-runtime-decisions", 0, "maximum runtime decision ordinal")
	maxScenarioDecisions := flags.Uint64("max-scenario-decisions", 0, "maximum scenario decision ordinal")
	maxNetworkDecisions := flags.Uint64("max-network-decisions", 0, "maximum network decision ordinal")
	maxStorageDecisions := flags.Uint64("max-storage-decisions", 0, "maximum storage decision ordinal")
	maxFaultDecisions := flags.Uint64("max-fault-decisions", 0, "maximum fault decision ordinal")
	maxCrashDecisions := flags.Uint64("max-crash-decisions", 0, "maximum crash-state decision ordinal")
	parallel := flags.Int("parallel", min(runtime.NumCPU(), 8), "maximum active targets")
	runTimeout := flags.Duration("execution-timeout", 30*time.Second, "per-execution host deadline")
	overallTimeout := flags.Duration("overall-timeout", 10*time.Minute, "complete exploration host deadline")
	terminateGrace := flags.Duration("terminate-grace", 2*time.Second, "termination grace inside deadlines")
	onFailure := flags.String("on-failure", string(runner.PolicyFirst), "first, budget, or all")
	failureBudget := flags.Uint64("failure-budget", 1, "distinct failure signature threshold")
	artifacts := flags.String("artifacts", ".gomad/artifacts", "artifact root")
	toolchainRoot := flags.String("toolchain-root", "", "absolute pinned toolchain root")
	capabilityMode := flags.String("capability-mode", string(target.CapabilityModeClosure), "closure, linked, or guarded capability assessment")
	jsonOutput := flags.Bool("json", false, "emit stable JSON events")
	planOutput := flags.String("output", "", "campaign plan output")
	choices := flags.Bool("choices", false, "record bounded runtime choices")
	diagnostics := flags.Bool("diagnostics", false, "record runtime-state diagnostics; implies --choices")
	coverage := flags.String("coverage", string(runner.CoverageNone), "none, semantic, choice, or semantic+choice")
	guide := flags.Bool("guide", false, "exclude answered seeds using a bounded coverage corpus")
	guideRegression := flags.Bool("guide-regression", false, "re-run corpus seeds with --guide; fully answered default requests execute zero seeds and exit 0")
	corpus := flags.String("corpus", "", "guided coverage corpus directory")
	keepSuccesses := flags.String("keep-successes", string(runner.KeepSuccessesNone), "none, novel, or all")
	successLimit := flags.Uint64("success-limit", 0, "maximum retained successful executions")
	outputLimit := byteSize(8 << 20)
	worldLimit := byteSize(64 << 20)
	successBytes := byteSize(0)
	choiceLimit := byteSize(8 << 20)
	explorationLimit := byteSize(0)
	explorationResultLimit := byteSize(0)
	flags.Var(&outputLimit, "output-limit", "retained bytes per output stream")
	flags.Var(&worldLimit, "world-transition-limit", "World transition capacity")
	flags.Var(&successBytes, "success-bytes", "total retained successful-execution bytes")
	flags.Var(&choiceLimit, "choice-bytes", "runtime choice trace capacity")
	transcriptLimit := byteSize(64 << 20)
	flags.Var(&transcriptLimit, "io-transcript-bytes", "I/O transcript capacity (64MiB to 1GiB, whole MiB)")
	flags.Var(&explorationLimit, "max-exploration-bytes", "maximum live choice-exploration bytes")
	flags.Var(&explorationResultLimit, "max-exploration-result-bytes", "maximum combined result bytes per candidate")
	var environment stringList
	var buildTags stringList
	var ioROMounts stringList
	var requiredSemanticProbes stringList
	flags.Var(&environment, "env", "target NAME=VALUE")
	flags.Var(&buildTags, "build-tag", "validated Go build tag")
	flags.Var(&ioROMounts, "io-ro-mount", "read-only HOST_DIRECTORY=TARGET_DIRECTORY mapping")
	flags.Var(&requiredSemanticProbes, "require-probe", "required semantic probe (requires --coverage=semantic)")
	workingDir := flags.String("working-dir", "", "absolute target module root (default: the current directory)")
	clockTick := flags.String("clock-tick", record.ClockTickStrict, "virtual-clock tick policy: strict or forward")
	if operation == planCampaign {
		// A portable plan completes all planned work. An explicit
		// --on-failure still parses over this fixed policy, and the plan
		// operation rejects any other.
		_ = flags.Set("on-failure", string(runner.PolicyAll))
	}
	if err := flags.Parse(arguments); err != nil {
		reporter := newExploreReporter(*jsonOutput, stdout, stderr)
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		if !*jsonOutput {
			flags.SetOutput(stderr)
			flags.Usage()
		}
		return campaignRequest{}, 2, false
	}
	reporter := newExploreReporter(*jsonOutput, stdout, stderr)
	if operation != planCampaign && *planOutput != "" {
		if writeErr := reporter.Error("invalid_input", errors.New("--output is only valid with gomad plan")); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	resolvedCapabilityMode, err := parseCapabilityMode(*capabilityMode)
	if err != nil {
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	var seedsSet, countSet, coverageSet, choiceLimitSet, maxRunsSet, maxChoiceDepthSet, choiceStartOrdinalSet, maxForcedDecisionsSet, maxExplorationBytesSet, maxExplorationResultBytesSet bool
	var runtimeLimitSet, scenarioLimitSet, networkLimitSet, storageLimitSet, faultLimitSet, crashLimitSet bool
	flags.Visit(func(visited *flag.Flag) {
		switch visited.Name {
		case "seeds":
			seedsSet = true
		case "count":
			countSet = true
		case "coverage":
			coverageSet = true
		case "choice-bytes":
			choiceLimitSet = true
		case "max-executions":
			maxRunsSet = true
		case "max-choice-depth":
			maxChoiceDepthSet = true
		case "choice-start-ordinal":
			choiceStartOrdinalSet = true
		case "max-forced-decisions":
			maxForcedDecisionsSet = true
		case "max-exploration-bytes":
			maxExplorationBytesSet = true
		case "max-exploration-result-bytes":
			maxExplorationResultBytesSet = true
		case "max-runtime-decisions":
			runtimeLimitSet = true
		case "max-scenario-decisions":
			scenarioLimitSet = true
		case "max-network-decisions":
			networkLimitSet = true
		case "max-storage-decisions":
			storageLimitSet = true
		case "max-fault-decisions":
			faultLimitSet = true
		case "max-crash-decisions":
			crashLimitSet = true
		}
	})
	resolvedStrategy, resolvedChoices, err := resolveExploreStrategy(exploreStrategyOptions{
		Value: *strategy, Seeds: *seeds, CountSet: countSet, Guide: *guide, Choices: *choices || *diagnostics,
		MaxExecutions: *maxRuns, MaxChoiceDepth: *maxChoiceDepth, MaxForcedDecisions: *maxForcedDecisions,
		MaxExplorationBytes: explorationLimit, MaxExplorationResultBytes: explorationResultLimit,
		SimulationDimensionLimits: runner.SimulationDimensionLimits{
			Runtime: *maxRuntimeDecisions, Scenario: *maxScenarioDecisions, Network: *maxNetworkDecisions,
			Storage: *maxStorageDecisions, Fault: *maxFaultDecisions, Crash: *maxCrashDecisions,
		},
		MaxExecutionsSet: maxRunsSet, MaxChoiceDepthSet: maxChoiceDepthSet, ChoiceStartOrdinalSet: choiceStartOrdinalSet, MaxForcedDecisionsSet: maxForcedDecisionsSet,
		MaxExplorationBytesSet: maxExplorationBytesSet, MaxExplorationResultBytesSet: maxExplorationResultBytesSet,
		RuntimeLimitSet: runtimeLimitSet, ScenarioLimitSet: scenarioLimitSet, NetworkLimitSet: networkLimitSet,
		StorageLimitSet: storageLimitSet, FaultLimitSet: faultLimitSet, CrashLimitSet: crashLimitSet,
	})
	if err != nil {
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	resolvedSeeds, err := resolveExploreSeeds(*seeds, *count, seedsSet, countSet)
	if err != nil {
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	if *guideRegression && !*guide {
		if err := reporter.Error("invalid_input", errors.New("--guide-regression requires --guide")); err != nil {
			fmt.Fprintln(stderr, err)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	resolvedCoverage, err := resolveExploreGuidance(*guide, *corpus, *coverage, coverageSet)
	if err != nil {
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	coverageMode, err := resolveExploreCoverage(resolvedCoverage, requiredSemanticProbes)
	if err != nil {
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	if *diagnostics && resolvedStrategy != runner.StrategySeed {
		if err := reporter.Error("invalid_input", errors.New("--diagnostics requires the seed strategy; forced-prefix exploration is unsupported")); err != nil {
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	resolvedChoiceLimit, err := resolveChoiceTrace(resolvedChoices, choiceLimit, choiceLimitSet)
	if err != nil {
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	if err := runner.ValidateChoiceCoverage(coverageMode, resolvedChoiceLimit); err != nil {
		if writeErr := reporter.Error("invalid_input", fmt.Errorf("--coverage=%s requires --choices", coverageMode)); writeErr != nil {
			if _, printErr := fmt.Fprintln(stderr, writeErr); printErr != nil {
				return campaignRequest{}, 3, false
			}
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	parsedTarget, err := parseTarget(flags.Args())
	if err != nil {
		if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
			return campaignRequest{}, 3, false
		}
		return campaignRequest{}, 2, false
	}
	workingDirectory, err := resolveWorkingDirectory(*workingDir, dependencies.workingDirectory)
	if err != nil {
		var invalid invalidWorkingDirectoryError
		if errors.As(err, &invalid) {
			if writeErr := reporter.Error("invalid_input", err); writeErr != nil {
				fmt.Fprintln(stderr, writeErr)
				return campaignRequest{}, 3, false
			}
			return campaignRequest{}, 2, false
		}
		if writeErr := reporter.Error("runner_failure", fmt.Errorf("resolve working directory: %w", err)); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
		}
		return campaignRequest{}, 3, false
	}
	installed, err := dependencies.install(*toolchainRoot)
	if err != nil {
		if writeErr := reporter.Error("runner_failure", err); writeErr != nil {
			fmt.Fprintln(stderr, writeErr)
		}
		return campaignRequest{}, 3, false
	}
	config := runner.CampaignSpec{
		Strategy: resolvedStrategy, Seeds: resolvedSeeds, Parallel: *parallel, ExecutionTimeout: *runTimeout, OverallTimeout: *overallTimeout, TerminateGrace: *terminateGrace,
		OnFailure: runner.FailurePolicy(*onFailure), FailureBudget: *failureBudget, OutputLimit: uint64(outputLimit), WorldTransitionLimit: uint64(worldLimit),
		Diagnostics: *diagnostics, ChoiceTraceLimit: resolvedChoiceLimit, ClockTick: *clockTick, IOTranscriptLimit: uint64(transcriptLimit), MaxExecutions: *maxRuns, MaxChoiceDepth: *maxChoiceDepth, ChoiceStartOrdinal: *choiceStartOrdinal, MaxForcedDecisions: *maxForcedDecisions,
		MaxExplorationBytes: uint64(explorationLimit), MaxExplorationResultBytes: uint64(explorationResultLimit),
		SimulationDimensionLimits: runner.SimulationDimensionLimits{
			Runtime: *maxRuntimeDecisions, Scenario: *maxScenarioDecisions, Network: *maxNetworkDecisions,
			Storage: *maxStorageDecisions, Fault: *maxFaultDecisions, Crash: *maxCrashDecisions,
		},
		Artifacts: *artifacts, Environment: environment, IOROMounts: ioROMounts, SupervisorCommand: installed.supervisorCommand(), CoordinatorCommand: installed.coordinatorCommand(), RunnerBuild: installed.runnerBuild,
		Coverage: coverageMode, RequiredSemanticProbes: requiredSemanticProbes,
		KeepSuccesses: runner.KeepSuccesses(*keepSuccesses), SuccessArtifactLimit: *successLimit, SuccessBytesLimit: uint64(successBytes),
		Guide: *guide, GuideRegression: *guideRegression, Corpus: *corpus,
		Progress: reporter.Progress, ProgressInterval: 5 * time.Second,
		Target: target.Spec{
			Kind: parsedTarget.kind, Source: parsedTarget.source, Provenance: parsedTarget.provenance, Args: parsedTarget.arguments,
			BuildTags: buildTags, WorkingDir: workingDirectory, ToolchainRoot: installed.toolchainRoot, CapabilityMode: resolvedCapabilityMode,
		},
	}
	return campaignRequest{campaign: config, output: *planOutput, json: *jsonOutput, reporter: reporter}, 0, true
}

type exploreStrategyOptions struct {
	Value                        string
	Seeds                        string
	CountSet                     bool
	Guide                        bool
	Choices                      bool
	MaxExecutions                uint64
	MaxChoiceDepth               uint64
	MaxForcedDecisions           uint64
	MaxExplorationBytes          byteSize
	MaxExplorationResultBytes    byteSize
	SimulationDimensionLimits    runner.SimulationDimensionLimits
	MaxExecutionsSet             bool
	MaxChoiceDepthSet            bool
	ChoiceStartOrdinalSet        bool
	MaxForcedDecisionsSet        bool
	MaxExplorationBytesSet       bool
	MaxExplorationResultBytesSet bool
	RuntimeLimitSet              bool
	ScenarioLimitSet             bool
	NetworkLimitSet              bool
	StorageLimitSet              bool
	FaultLimitSet                bool
	CrashLimitSet                bool
}

// resolveExploreStrategy checks the exploration flags given for the strategy
// Runner reads from --strategy, and reports whether the strategy records
// choices.

func resolveExploreStrategy(options exploreStrategyOptions) (runner.Strategy, bool, error) {
	strategy, err := runner.ParseStrategy(options.Value)
	if err != nil {
		return "", false, err
	}
	switch strategy {
	case runner.StrategySeed:
		if options.hasCombinedBounds() {
			return "", false, errors.New("simulation exploration bounds require --strategy=simulation-exploration")
		}
		if options.MaxExecutionsSet || options.MaxChoiceDepthSet || options.MaxExplorationBytesSet {
			return "", false, errors.New("exploration bounds require --strategy=choice-exploration")
		}
		if options.ChoiceStartOrdinalSet {
			return "", false, errors.New("--choice-start-ordinal requires --strategy=choice-exploration")
		}
		return strategy, options.Choices, nil
	case runner.StrategyChoiceExploration:
		if options.hasCombinedBounds() {
			return "", false, errors.New("simulation exploration bounds require --strategy=simulation-exploration")
		}
		if options.CountSet {
			return "", false, errors.New("--strategy=choice-exploration does not accept --count")
		}
		if _, err := runner.ParseSingleBaseSeed(options.Seeds); err != nil {
			var single *runner.NotSingleBaseSeedError
			if errors.As(err, &single) {
				return "", false, errors.New("--strategy=choice-exploration requires exactly one base seed")
			}
			return "", false, err
		}
		if options.Guide {
			return "", false, errors.New("--strategy=choice-exploration does not support --guide")
		}
		if !options.MaxExecutionsSet || options.MaxExecutions == 0 {
			return "", false, errors.New("--strategy=choice-exploration requires an explicit positive --max-executions")
		}
		if !options.MaxChoiceDepthSet || options.MaxChoiceDepth == 0 {
			return "", false, errors.New("--strategy=choice-exploration requires an explicit positive --max-choice-depth")
		}
		if !options.MaxExplorationBytesSet || options.MaxExplorationBytes == 0 {
			return "", false, errors.New("--strategy=choice-exploration requires an explicit positive --max-exploration-bytes")
		}
		return strategy, true, nil
	case runner.StrategySimulationExploration:
		if options.CountSet {
			return "", false, errors.New("--strategy=simulation-exploration does not accept --count")
		}
		if _, err := runner.ParseSingleBaseSeed(options.Seeds); err != nil {
			var single *runner.NotSingleBaseSeedError
			if errors.As(err, &single) {
				return "", false, errors.New("--strategy=simulation-exploration requires exactly one base seed")
			}
			return "", false, err
		}
		if options.Guide {
			return "", false, errors.New("--strategy=simulation-exploration does not support --guide")
		}
		if options.MaxChoiceDepthSet {
			return "", false, errors.New("--strategy=simulation-exploration does not accept --max-choice-depth")
		}
		if options.ChoiceStartOrdinalSet {
			return "", false, errors.New("--strategy=simulation-exploration does not accept --choice-start-ordinal")
		}
		for _, bound := range []struct {
			name  string
			value uint64
			set   bool
		}{
			{name: "--max-executions", value: options.MaxExecutions, set: options.MaxExecutionsSet},
			{name: "--max-forced-decisions", value: options.MaxForcedDecisions, set: options.MaxForcedDecisionsSet},
			{name: "--max-exploration-bytes", value: uint64(options.MaxExplorationBytes), set: options.MaxExplorationBytesSet},
			{name: "--max-exploration-result-bytes", value: uint64(options.MaxExplorationResultBytes), set: options.MaxExplorationResultBytesSet},
			{name: "--max-runtime-decisions", value: options.SimulationDimensionLimits.Runtime, set: options.RuntimeLimitSet},
			{name: "--max-scenario-decisions", value: options.SimulationDimensionLimits.Scenario, set: options.ScenarioLimitSet},
			{name: "--max-network-decisions", value: options.SimulationDimensionLimits.Network, set: options.NetworkLimitSet},
			{name: "--max-storage-decisions", value: options.SimulationDimensionLimits.Storage, set: options.StorageLimitSet},
			{name: "--max-fault-decisions", value: options.SimulationDimensionLimits.Fault, set: options.FaultLimitSet},
			{name: "--max-crash-decisions", value: options.SimulationDimensionLimits.Crash, set: options.CrashLimitSet},
		} {
			if !bound.set || bound.value == 0 {
				return "", false, fmt.Errorf("--strategy=simulation-exploration requires an explicit positive %s", bound.name)
			}
		}
		return strategy, true, nil
	default:
		// Runner knows a strategy this command has no flags for.
		return "", false, fmt.Errorf("gomad explore does not support strategy %q", strategy)
	}
}

func resolveExploreGuidance(enabled bool, corpus, coverage string, coverageSet bool) (string, error) {
	if !enabled {
		if corpus != "" {
			return "", fmt.Errorf("--corpus requires --guide")
		}
		return coverage, nil
	}
	if corpus == "" {
		return "", fmt.Errorf("--guide requires --corpus DIR")
	}
	if coverageSet && coverage != string(runner.CoverageSemantic) && coverage != string(runner.CoverageChoice) && coverage != string(runner.CoverageSemanticChoice) {
		return "", errors.New("--guide requires semantic or choice coverage")
	}
	if !coverageSet {
		return string(runner.NormalizeCoverage("", true)), nil
	}
	return coverage, nil
}

func resolveExploreSeeds(seeds string, count uint64, seedsSet, countSet bool) (string, error) {
	if seedsSet && countSet {
		return "", fmt.Errorf("--count and --seeds are mutually exclusive")
	}
	if !countSet {
		return seeds, nil
	}
	if count == 0 {
		return "", fmt.Errorf("--count must be greater than zero")
	}
	if count == 1 {
		return "0", nil
	}
	return "0-" + strconv.FormatUint(count-1, 10), nil
}

// resolveExploreCoverage reads --coverage through Runner and checks the
// --require-probe flags given for it.

func resolveExploreCoverage(value string, required []string) (runner.CoverageMode, error) {
	mode, err := runner.ParseCoverageMode(value)
	if err != nil {
		return "", err
	}
	if err := runner.ValidateCoverage(mode, required); err != nil {
		var required *runner.SemanticCoverageRequiredError
		if errors.As(err, &required) {
			return "", errors.New("--require-probe requires --coverage=semantic")
		}
		return "", err
	}
	return mode, nil
}

func resolveChoiceTrace(enabled bool, limit byteSize, limitSet bool) (uint64, error) {
	if !enabled {
		if limitSet {
			return 0, fmt.Errorf("--choice-bytes requires --choices")
		}
		return 0, nil
	}
	if limit == 0 {
		return 0, fmt.Errorf("--choice-bytes must be between %d bytes and 64MiB", runner.MinimumChoiceTraceBytes)
	}
	if err := runner.ValidateChoiceTraceLimit(uint64(limit)); err != nil {
		return 0, fmt.Errorf("--choice-bytes must be between %d bytes and 64MiB", runner.MinimumChoiceTraceBytes)
	}
	return uint64(limit), nil
}

type replayDependencies struct {
	install func(string) (installation, error)
	replay  func(context.Context, runner.ReplaySpec) (runner.ReplayResult, error)
}

func NormalizeStrategy(strategy Strategy) Strategy {
	if strategy == "" {
		return StrategySeed
	}
	return strategy
}

func NormalizeCoverage(mode CoverageMode, guided bool) CoverageMode {
	if mode == "" {
		if guided {
			return CoverageSemantic
		}
		return CoverageNone
	}
	return mode
}

func ValidateCoverage(mode CoverageMode, required []string) error {
	switch mode {
	case "", CoverageNone, CoverageChoice:
		if len(required) != 0 {
			return &SemanticCoverageRequiredError{}
		}
	case CoverageSemantic, CoverageSemanticChoice:
		if _, err := deterministicio.MissingRequiredSemanticProbes(deterministicio.SemanticCoverage{}, required); err != nil {
			return err
		}
	default:
		return fmt.Errorf("unknown coverage mode %q", mode)
	}
	return nil
}

func ValidateChoiceTraceLimit(limit uint64) error {
	if limit != 0 && (limit < MinimumChoiceTraceBytes || limit > MaximumChoiceTraceBytes) {
		return fmt.Errorf("choice trace capacity must be between %d bytes and 64 MiB", MinimumChoiceTraceBytes)
	}
	return nil
}

func ValidateChoiceCoverage(mode CoverageMode, choiceTraceLimit uint64) error {
	if coverageHasChoice(mode) && choiceTraceLimit == 0 {
		return errors.New("choice coverage requires an enabled choice trace")
	}
	return nil
}

func ParseSingleBaseSeed(seeds string) (SeedSelection, error) {
	selection, err := ParseSeeds(seeds)
	if err != nil {
		return SeedSelection{}, err
	}
	if err := requireSingleBaseSeed(selection); err != nil {
		return SeedSelection{}, err
	}
	return selection, nil
}

func requireSingleBaseSeed(selection SeedSelection) error {
	if selection.Count() != 1 {
		return &NotSingleBaseSeedError{}
	}
	return nil
}

func campaignRequestFromSpecWith(spec CampaignSpec, dependencies executionDependencies) campaignRequest {
	request := campaignRequestFromSpec(spec)
	request.executor = dependencies.executor
	return request
}

func campaignRequestFromSpec(spec CampaignSpec) campaignRequest {
	spec.Environment = append([]string(nil), spec.Environment...)
	spec.IOROMounts = append([]string(nil), spec.IOROMounts...)
	spec.RequiredSemanticProbes = append([]string(nil), spec.RequiredSemanticProbes...)
	spec.SupervisorCommand = append([]string(nil), spec.SupervisorCommand...)
	spec.CoordinatorCommand = append([]string(nil), spec.CoordinatorCommand...)
	spec.Target.Args = append([]string(nil), spec.Target.Args...)
	spec.Target.BuildTags = append([]string(nil), spec.Target.BuildTags...)
	spec.Target.AdapterReplacements = append([]target.AdapterReplacement(nil), spec.Target.AdapterReplacements...)
	if spec.GuideRegressionOverride != nil {
		value := *spec.GuideRegressionOverride
		spec.GuideRegressionOverride = &value
	}
	request := campaignRequest{
		campaignOptions: campaignOptions{
			campaignIdentityOptions: campaignIdentityOptions{
				ResumeCampaign: spec.ResumeCampaign, PlanSHA256: spec.PlanSHA256, Shard: spec.Shard, Artifacts: spec.Artifacts,
			},
			campaignTargetOptions: campaignTargetOptions{
				Target: spec.Target, Environment: spec.Environment, IOROMounts: spec.IOROMounts, IOROMountLimits: spec.IOROMountLimits,
			},
			campaignSearchOptions: campaignSearchOptions{
				Strategy: spec.Strategy, Seeds: spec.Seeds, MaxExecutions: spec.MaxExecutions, MaxChoiceDepth: spec.MaxChoiceDepth,
				ChoiceStartOrdinal: spec.ChoiceStartOrdinal, MaxForcedDecisions: spec.MaxForcedDecisions,
				MaxExplorationBytes: spec.MaxExplorationBytes, MaxExplorationResultBytes: spec.MaxExplorationResultBytes,
				SimulationDimensionLimits: spec.SimulationDimensionLimits, OnFailure: spec.OnFailure, FailureBudget: spec.FailureBudget,
			},
			campaignResourceOptions: campaignResourceOptions{
				Parallel: spec.Parallel, ExecutionTimeout: spec.ExecutionTimeout, OverallTimeout: spec.OverallTimeout,
				TerminateGrace: spec.TerminateGrace, OutputLimit: spec.OutputLimit, WorldTransitionLimit: spec.WorldTransitionLimit,
			},
			campaignObservationOptions: campaignObservationOptions{
				Diagnostics: spec.Diagnostics, ChoiceTraceLimit: spec.ChoiceTraceLimit, IOTranscriptLimit: spec.IOTranscriptLimit,
				ClockTick: spec.ClockTick, Coverage: spec.Coverage, RequiredSemanticProbes: spec.RequiredSemanticProbes,
				CollectExecutionEvidence: spec.CollectExecutionEvidence, ProgressInterval: spec.ProgressInterval,
			},
			campaignRetentionOptions: campaignRetentionOptions{
				KeepSuccesses: spec.KeepSuccesses, SuccessArtifactLimit: spec.SuccessArtifactLimit, SuccessBytesLimit: spec.SuccessBytesLimit,
			},
			campaignGuidanceOptions: campaignGuidanceOptions{
				Guide: spec.Guide, GuideRegression: spec.GuideRegression, GuideRegressionOverride: spec.GuideRegressionOverride,
				Corpus: spec.Corpus, GuideSnapshotSHA256: spec.GuideSnapshotSHA256,
			},
		},
		campaignRuntime: campaignRuntime{
			SupervisorCommand: spec.SupervisorCommand, CoordinatorCommand: spec.CoordinatorCommand, RunnerBuild: spec.RunnerBuild,
			Progress: spec.Progress, Preparer: spec.Preparer, Replayer: spec.Replayer,
			guidancePlan: spec.guidancePlan, resumePreflight: spec.resumePreflight,
			failureArtifactLimit: spec.failureArtifactLimit, failureBytesLimit: spec.failureBytesLimit,
		},
	}
	request.normalize()
	return request
}

func validateConfig(config CampaignSpec) (SeedSelection, []record.Environment, error) {
	return validateCampaignRequest(campaignRequestFromSpec(config))
}

func validateCampaignRequest(config campaignRequest) (SeedSelection, []record.Environment, error) {
	if config.ResumeCampaign != "" {
		if config.Preparer != nil {
			return SeedSelection{}, nil, fmt.Errorf("campaign resume does not accept target preparation")
		}
		if config.RunnerBuild == "" {
			return SeedSelection{}, nil, fmt.Errorf("Runner build identity is required for campaign resume")
		}
		if config.executor == nil && len(config.SupervisorCommand) == 0 {
			return SeedSelection{}, nil, fmt.Errorf("supervisor command is required")
		}
		return SeedSelection{}, nil, nil
	}
	selection, err := ParseSeeds(config.Seeds)
	if config.guidancePlan != nil {
		selection, err = parseCampaignSelection(config.Seeds, uint64(config.guidancePlan.RequestedCount-config.guidancePlan.AnsweredCount))
	}
	if err != nil {
		return SeedSelection{}, nil, err
	}
	strategy := config.strategy()
	shard := config.shard()
	if err := shard.Validate(); err != nil {
		return SeedSelection{}, nil, err
	}
	if config.Shard.Count != 0 {
		if config.PlanSHA256 == "" {
			return SeedSelection{}, nil, errors.New("sharded campaign requires a canonical plan identity")
		}
		if _, err := record.ParseSHA256(string(config.PlanSHA256)); err != nil {
			return SeedSelection{}, nil, fmt.Errorf("canonical plan identity: %w", err)
		}
		if strategy != StrategySeed || config.Guide && config.guidancePlan == nil {
			return SeedSelection{}, nil, errors.New("static sharding requires a seed campaign with frozen guidance")
		}
		if config.OnFailure != PolicyAll {
			return SeedSelection{}, nil, errors.New("sharded campaign requires on-failure=all")
		}
	}
	switch strategy {
	case StrategySeed:
		if config.MaxExecutions != 0 || config.MaxChoiceDepth != 0 || config.ChoiceStartOrdinal != 0 || config.MaxForcedDecisions != 0 || config.MaxExplorationBytes != 0 || config.MaxExplorationResultBytes != 0 || config.SimulationDimensionLimits != (SimulationDimensionLimits{}) {
			return SeedSelection{}, nil, errors.New("exploration bounds require the choice-exploration strategy")
		}
	case StrategyChoiceExploration:
		if config.MaxForcedDecisions != 0 || config.MaxExplorationResultBytes != 0 || config.SimulationDimensionLimits != (SimulationDimensionLimits{}) {
			return SeedSelection{}, nil, errors.New("simulation exploration bounds require the simulation-exploration strategy")
		}
		if err := requireSingleBaseSeed(selection); err != nil {
			return SeedSelection{}, nil, errors.New("choice-exploration exploration requires exactly one base seed")
		}
		if config.Guide {
			return SeedSelection{}, nil, errors.New("choice-exploration strategy does not support guided exploration")
		}
		if config.ChoiceTraceLimit == 0 {
			return SeedSelection{}, nil, errors.New("choice-exploration strategy requires an enabled choice trace")
		}
		if config.MaxExecutions == 0 {
			return SeedSelection{}, nil, errors.New("choice-exploration max executions must be positive")
		}
		if config.MaxChoiceDepth == 0 {
			return SeedSelection{}, nil, errors.New("choice-exploration choice depth must be positive")
		}
		if config.MaxExplorationBytes == 0 {
			return SeedSelection{}, nil, errors.New("choice-exploration exploration bytes must be positive")
		}
	case StrategySimulationExploration:
		if err := requireSingleBaseSeed(selection); err != nil {
			return SeedSelection{}, nil, errors.New("simulation-exploration exploration requires exactly one base seed")
		}
		if config.Guide {
			return SeedSelection{}, nil, errors.New("simulation-exploration strategy does not support guided exploration")
		}
		if config.ChoiceTraceLimit == 0 {
			return SeedSelection{}, nil, errors.New("simulation-exploration strategy requires an enabled choice trace")
		}
		if config.MaxExecutions == 0 {
			return SeedSelection{}, nil, errors.New("simulation-exploration max executions must be positive")
		}
		if config.MaxChoiceDepth != 0 {
			return SeedSelection{}, nil, errors.New("choice depth requires the choice-exploration strategy")
		}
		if config.ChoiceStartOrdinal != 0 {
			return SeedSelection{}, nil, errors.New("choice start ordinal requires the choice-exploration strategy")
		}
		if config.MaxForcedDecisions == 0 {
			return SeedSelection{}, nil, errors.New("simulation-exploration forced decisions must be positive")
		}
		if config.MaxExplorationBytes == 0 {
			return SeedSelection{}, nil, errors.New("simulation-exploration exploration bytes must be positive")
		}
		if config.MaxExplorationResultBytes == 0 {
			return SeedSelection{}, nil, errors.New("simulation-exploration result bytes must be positive")
		}
		if err := validateSimulationDimensionLimits(config.SimulationDimensionLimits); err != nil {
			return SeedSelection{}, nil, err
		}
	default:
		return SeedSelection{}, nil, fmt.Errorf("unknown exploration strategy %q", config.Strategy)
	}
	if config.Parallel <= 0 {
		return SeedSelection{}, nil, fmt.Errorf("parallelism must be positive")
	}
	if config.ExecutionTimeout <= 0 || config.OverallTimeout <= 0 {
		return SeedSelection{}, nil, errors.New("execution and overall timeouts must be positive")
	}
	if config.TerminateGrace < 0 || config.TerminateGrace > config.ExecutionTimeout || config.TerminateGrace > config.OverallTimeout {
		return SeedSelection{}, nil, errors.New("termination grace must fit inside all deadlines")
	}
	if config.OutputLimit == 0 || config.WorldTransitionLimit == 0 {
		return SeedSelection{}, nil, errors.New("output and World transition limits must be positive")
	}
	if config.Diagnostics && (config.ChoiceTraceLimit == 0 || config.strategy() != StrategySeed) {
		return SeedSelection{}, nil, errors.New("diagnostics require choice recording with the seed strategy")
	}
	if err := ValidateChoiceTraceLimit(config.ChoiceTraceLimit); err != nil {
		return SeedSelection{}, nil, err
	}
	if config.Artifacts == "" || config.RunnerBuild == "" {
		return SeedSelection{}, nil, errors.New("artifact root and Runner build identity are required")
	}
	if err := ValidateCoverage(config.Coverage, config.RequiredSemanticProbes); err != nil {
		return SeedSelection{}, nil, err
	}
	if err := ValidateChoiceCoverage(config.Coverage, config.ChoiceTraceLimit); err != nil {
		return SeedSelection{}, nil, err
	}
	switch normalizedKeepSuccesses(config.KeepSuccesses) {
	case KeepSuccessesNone:
		if config.SuccessArtifactLimit != 0 || config.SuccessBytesLimit != 0 {
			return SeedSelection{}, nil, errors.New("disabled success retention does not accept capacity limits")
		}
	case KeepSuccessesNovel:
		if NormalizeCoverage(config.Coverage, false) == CoverageNone || config.SuccessArtifactLimit == 0 || config.SuccessBytesLimit == 0 {
			return SeedSelection{}, nil, errors.New("novel success retention requires coverage and explicit count and byte limits")
		}
	case KeepSuccessesAll:
		if config.SuccessArtifactLimit == 0 || config.SuccessBytesLimit == 0 {
			return SeedSelection{}, nil, errors.New("success retention requires explicit count and byte limits")
		}
	default:
		return SeedSelection{}, nil, fmt.Errorf("unknown successful-execution retention policy %q", config.KeepSuccesses)
	}
	if config.CollectExecutionEvidence && (selection.Count() != 1 || !coverageHasSemantic(config.Coverage)) {
		return SeedSelection{}, nil, errors.New("execution evidence requires exactly one seed and semantic coverage")
	}
	if config.Guide {
		if config.Corpus == "" || NormalizeCoverage(config.Coverage, false) == CoverageNone {
			return SeedSelection{}, nil, errors.New("guided exploration requires a corpus and coverage")
		}
	} else if config.GuideRegression || config.Corpus != "" || config.GuideSnapshotSHA256 != "" {
		return SeedSelection{}, nil, errors.New("a guided corpus requires guided exploration")
	}
	switch config.OnFailure {
	case PolicyFirst, PolicyAll:
		if config.FailureBudget != 1 {
			return SeedSelection{}, nil, errors.New("failure budget is only configurable in budget mode")
		}
	case PolicyBudget:
		if config.FailureBudget == 0 {
			return SeedSelection{}, nil, errors.New("failure budget must be positive")
		}
	default:
		return SeedSelection{}, nil, fmt.Errorf("unknown failure policy %q", config.OnFailure)
	}
	if config.executor == nil && len(config.SupervisorCommand) == 0 {
		return SeedSelection{}, nil, errors.New("supervisor command is required")
	}
	if len(config.IOROMounts) != 0 {
		if config.Target.WorkingDir == "" {
			return SeedSelection{}, nil, errors.New("read-only mounts require a target working directory")
		}
		if _, err := readonlymount.ParseMappings(config.IOROMounts, config.Target.WorkingDir); err != nil {
			return SeedSelection{}, nil, err
		}
		limits := config.IOROMountLimits
		if limits == (readonlymount.Limits{}) {
			limits = readonlymount.DefaultLimits()
		}
		if _, err := readonlymount.Prepare(nil, limits); err != nil {
			return SeedSelection{}, nil, err
		}
	}
	environment, err := parseEnvironment(config.Environment)
	if err != nil {
		return SeedSelection{}, nil, err
	}
	environment = append(environment, record.Environment{Name: "GOMAD3_IO_PROFILE", Value: deterministicio.Deterministic})
	if err := deterministicio.ValidateTranscriptLimit(ioTranscriptLimit(config)); err != nil {
		return SeedSelection{}, nil, err
	}
	switch config.ClockTick {
	case "", record.ClockTickStrict:
	case record.ClockTickForward:
		environment = append(environment, record.Environment{Name: record.ClockTickEnvironment, Value: record.ClockTickForward})
	default:
		return SeedSelection{}, nil, fmt.Errorf("clock tick policy %q must be strict or forward", config.ClockTick)
	}
	if config.ChoiceTraceLimit != 0 {
		environment = append(environment, record.Environment{Name: "GOMAD3_CHOICE_PROFILE", Value: choice.Profile})
	}
	if config.Diagnostics {
		environment = append(environment, record.Environment{Name: choice.DiagnosticProfileEnvironment, Value: choice.DiagnosticProfile})
	}
	sort.Slice(environment, func(i, j int) bool { return environment[i].Name < environment[j].Name })
	return selection, environment, nil
}

func validateSimulationDimensionLimits(limits SimulationDimensionLimits) error {
	for _, dimension := range []struct {
		name  string
		limit uint64
	}{
		{name: "runtime", limit: limits.Runtime},
		{name: "scenario", limit: limits.Scenario},
		{name: "network", limit: limits.Network},
		{name: "storage", limit: limits.Storage},
		{name: "fault", limit: limits.Fault},
		{name: "crash", limit: limits.Crash},
	} {
		if dimension.limit == 0 {
			return fmt.Errorf("simulation-exploration %s dimension bound must be positive", dimension.name)
		}
	}
	return nil
}

func validateObservedChoiceTrace(limit uint64, capability *execution.ChoiceCapability, observed *execution.ChoiceTrace) error {
	if limit == 0 {
		return nil
	}
	if observed == nil || observed.Profile == "" || observed.Trace.Summary.Terminal == 0 {
		return execution.ErrChoiceTraceUnterminated
	}
	if capability == nil || observed.Profile != choice.Profile || observed.ImplementationSHA256 != capability.ImplementationSHA256 || observed.Limit != limit || observed.Trace.Summary.Terminal != choice.TerminalComplete {
		return execution.ErrChoiceTraceMalformed
	}
	tape, err := choice.ProjectReplayPlan(observed.Trace, capability.ExecutionIdentity)
	if err != nil {
		return errors.Join(execution.ErrChoiceTraceMalformed, err)
	}
	observed.TapeSHA256 = tape.SHA256
	observed.Decisions = uint64(len(tape.Decisions))
	return nil
}

func createCampaignPlanWith(ctx context.Context, spec CampaignPlanSpec, dependencies executionDependencies) (_ CampaignPlanResult, retErr error) {
	if ctx == nil {
		ctx = context.Background()
	}
	config := campaignRequestFromSpecWith(spec.Campaign, dependencies)
	selection, environment, err := validateCampaignRequest(config)
	if err != nil {
		return CampaignPlanResult{}, err
	}
	if config.strategy() != StrategySeed || config.OnFailure != PolicyAll {
		return CampaignPlanResult{}, errors.New("portable campaign plans require a seed campaign with on-failure=all")
	}
	if config.Shard.Count != 0 || config.PlanSHA256 != "" || config.ResumeCampaign != "" {
		return CampaignPlanResult{}, errors.New("portable campaign plan input cannot already be a shard or resume")
	}
	output, err := filepath.Abs(spec.Output)
	if err != nil || spec.Output == "" {
		return CampaignPlanResult{}, errors.Join(errors.New("resolve campaign plan output"), err)
	}
	bundle := output + campaignPlanBundleSuffix
	for _, path := range []string{output, bundle} {
		if _, err := os.Lstat(path); err == nil {
			return CampaignPlanResult{}, fmt.Errorf("campaign plan output already exists: %s", path)
		} else if !errors.Is(err, os.ErrNotExist) {
			return CampaignPlanResult{}, fmt.Errorf("inspect campaign plan output: %w", err)
		}
	}
	if err := os.MkdirAll(filepath.Dir(output), 0o700); err != nil {
		return CampaignPlanResult{}, fmt.Errorf("create campaign plan parent: %w", err)
	}
	if err := os.Mkdir(bundle, 0o700); err != nil {
		return CampaignPlanResult{}, fmt.Errorf("create campaign plan bundle: %w", err)
	}
	published := false
	defer func() {
		if !published {
			retErr = errors.Join(retErr, os.RemoveAll(bundle))
		}
	}()
	if config.IOROMountLimits == (readonlymount.Limits{}) {
		config.IOROMountLimits = readonlymount.DefaultLimits()
	}
	mounts, err := readonlymount.ParseMappings(config.IOROMounts, config.Target.WorkingDir)
	if err != nil {
		return CampaignPlanResult{}, err
	}
	mounts, portableMounts := canonicalCampaignPlanMounts(mounts)
	mountIdentity, capturedMounts, err := captureCampaignPlanMounts(mounts, config.IOROMountLimits)
	if err != nil {
		return CampaignPlanResult{}, fmt.Errorf("capture campaign plan mount identity: %w", err)
	}
	config.Target.PreparationRoot = bundle
	prepared, err := preparation.Prepare(ctx, preparation.Request{
		Target: config.Target, Environment: config.Environment, Preparer: config.Preparer,
	})
	if err != nil {
		return CampaignPlanResult{}, err
	}
	targetPath := filepath.Join(bundle, campaignPlanTargetFile)
	if filepath.Clean(prepared.Path) != targetPath {
		preparationDirectory := filepath.Dir(prepared.Path)
		relative, relativeErr := filepath.Rel(bundle, preparationDirectory)
		if relativeErr != nil || relative == "." || relative == ".." || filepath.IsAbs(relative) || len(relative) >= 3 && relative[:3] == ".."+string(filepath.Separator) {
			return CampaignPlanResult{}, errors.Join(errors.New("prepared campaign target is outside its private preparation directory"), relativeErr)
		}
		if err := os.Rename(prepared.Path, targetPath); err != nil {
			return CampaignPlanResult{}, fmt.Errorf("publish prepared campaign target: %w", err)
		}
		if err := os.RemoveAll(preparationDirectory); err != nil {
			return CampaignPlanResult{}, fmt.Errorf("remove campaign target preparation files: %w", err)
		}
	}
	if err := os.Chmod(targetPath, 0o500); err != nil {
		return CampaignPlanResult{}, fmt.Errorf("make campaign target immutable: %w", err)
	}
	prepared.Path = targetPath
	if err := prepared.Verify(); err != nil {
		return CampaignPlanResult{}, err
	}
	if err := materializeCampaignPlanMounts(bundle, capturedMounts); err != nil {
		return CampaignPlanResult{}, fmt.Errorf("materialize campaign plan mounts: %w", err)
	}
	if config.Guide {
		config.Corpus, err = guidedCorpusPath(config.Corpus)
		if err != nil {
			return CampaignPlanResult{}, err
		}
		guidance, err := openGuidance(ctx, config, prepared, environment, "plan")
		if err != nil {
			return CampaignPlanResult{}, err
		}
		snapshot := guidance.Snapshot()
		selection, config.guidancePlan, err = selectGuidedSeeds(selection, snapshot, config.Corpus, config.GuideRegression)
		err = errors.Join(err, guidance.Close())
		if err != nil {
			return CampaignPlanResult{}, err
		}
		config.Seeds = selection.String()
		config.GuideSnapshotSHA256 = snapshot.SnapshotSHA256
	}
	journalPlan, err := campaign.DeriveExecutionJournalPlan(string(StrategySeed), selection.Count(), 0, uint64(config.Parallel))
	if err != nil {
		return CampaignPlanResult{}, fmt.Errorf("derive campaign journal capacity: %w", err)
	}
	plan, err := campaignPlanRecord(config, journalPlan, ".prepared/target", prepared, environment, portableMounts, selection.Count())
	if err != nil {
		return CampaignPlanResult{}, err
	}
	if err := campaign.ValidateCampaignPlan(plan); err != nil {
		return CampaignPlanResult{}, err
	}
	document := portableCampaignPlan{Schema: campaignPlanSchema, Mapping: campaignPlanMapping, Mounts: mountIdentity, Campaign: plan}
	encoded, err := canonicaljson.CanonicalJSON(document)
	if err != nil {
		return CampaignPlanResult{}, fmt.Errorf("encode campaign plan: %w", err)
	}
	if len(encoded) > maximumCampaignPlanBytes {
		return CampaignPlanResult{}, fmt.Errorf("campaign plan exceeds its %d-byte capacity", maximumCampaignPlanBytes)
	}
	if err := syncRegularFile(targetPath); err != nil {
		return CampaignPlanResult{}, err
	}
	if err := syncDirectory(bundle); err != nil {
		return CampaignPlanResult{}, err
	}
	if err := publishPlanFile(output, encoded); err != nil {
		return CampaignPlanResult{}, err
	}
	published = true
	return CampaignPlanResult{
		Path: output, BundlePath: bundle, SHA256: record.HashBytes(encoded), SelectionCount: selection.Count(), TargetSHA256: record.SHA256(prepared.SHA256),
	}, nil
}

func validateCampaignPlanMountIdentity(plan campaign.CampaignPlan, identity *campaignPlanMountIdentity, bundle string) error {
	if identity == nil {
		if len(plan.IOROMounts) != 0 {
			return errors.New("campaign plan mount identity is missing")
		}
		return nil
	}
	mappings, err := readonlymount.ParseMappings(plan.IOROMounts, bundle)
	if err != nil {
		return err
	}
	limits, err := readonlymount.DecodeLimits(deterministicCapturedInputLimits(plan.IOROMountLimits))
	if err != nil {
		return err
	}
	targets := make([]string, len(mappings))
	for index, mapping := range mappings {
		targets[index] = mapping.Target
	}
	if identity.Schema != "gomad3.io-read-only-mounts/v1" || identity.SHA256 == "" || identity.Bytes == 0 || identity.Entries < record.Uint64String(len(mappings)) || !slices.Equal(identity.Mappings, targets) || identity.Limits != readonlymount.CapturedInputLimitsOf(limits) {
		return errors.New("campaign plan mount identity is invalid")
	}
	if _, err := record.ParseSHA256(string(identity.SHA256)); err != nil {
		return fmt.Errorf("campaign plan mount identity: %w", err)
	}
	for index, mapping := range mappings {
		if plan.IOROMounts[index] != campaignPlanMountValue(index, mapping.Target) {
			return errors.New("campaign plan mount mapping is not portable")
		}
	}
	actual, _, err := captureCampaignPlanMounts(mappings, limits)
	if err != nil {
		return fmt.Errorf("verify campaign plan mount identity: %w", err)
	}
	if !equalCampaignPlanMountIdentity(actual, identity) {
		return errors.New("campaign plan read-only mount identity changed")
	}
	return nil
}

