func TestMixGuidedSelectionReservesOneQuarterForUnguidedSeeds(t *testing.T) {
	selection, err := ParseSeeds("0-7")
	if err != nil {
		t.Fatal(err)
	}
	mixed, err := mixGuidedSelection(selection, []uint64{100, 101, 102, 103, 104, 105, 106})
