		TerminateGrace: time.Second, OnFailure: PolicyAll, FailureBudget: 1,
		OutputLimit: 1 << 20, WorldTransitionLimit: 1 << 20,
		Artifacts: "/tmp/gomad-campaign-options", Environment: []string{"MODE=baseline"},
